"use client"

import * as React from "react"
import { cn } from "cn"

import { TextField } from "@/components/standard/text-field"

function AutocompleteInput({
  className,
  options,
  ...props
}: Omit<React.ComponentProps<typeof TextField>, "list"> & {
  options: string[]
}) {
  const listId = React.useId()

  return (
    <div data-slot="autocomplete-input" className={cn("w-full", className)}>
      <TextField list={listId} {...props} />
      <datalist id={listId}>
        {options.map((option) => (
          <option key={option} value={option} />
        ))}
      </datalist>
    </div>
  )
}

export { AutocompleteInput }
